distinct_index &lt;- function(d, o) {                     # where each entry of u_a sits among its distinct entries
  tri &lt;- outer(0:(d - 1), 0:(d - 1), \(j, m) pmax(j, m) * (pmax(j, m) + 1) / 2 + pmin(j, m))
  nt &lt;- d * (d + 1) / 2
  c(seq_len(d * o), d * o + 1 + as.vector(tri), d * o + nt + 1 + as.vector(tri))
}

compress_rows &lt;- function(df, R, Y = as.matrix(df[y_cols])) {        # profile rows to the compressed dataset
  stopifnot(!is.unsorted(df$account))                                 # each account's rows are together
  accounts &lt;- df |&gt;
    distinct(account, Z, day, w) |&gt;
    arrange(account)
  strata &lt;- group_by(accounts, Z, day, w)
  h &lt;- group_indices(strata)
  k &lt;- compress_profiles(df$account, h[match(df$account, accounts$account)], R, df$T, Y, max(h))
  i &lt;- distinct_index(ncol(R), ncol(Y))
  group_keys(strata) |&gt;
    mutate(G = k$G, first_moments = map(seq_len(n()), \(s) k$first[s, i]), second_moments = map(k$second, \(m) m[i, i]))
}

