Exact: draw the weights during the compression pass
The previous post built each account summary \(u_a\) in one pass over the profile rows, added it into its stratum’s sums, and discarded it. We change one line: instead of adding \(u_a\) once, we add \(\xi^{(b)}_a v_a\) for every draw \(b\). The pass then produces, for every stratum, a \(B \times (1 + \dim u_a)\) matrix whose row \(b\) is the weighted sum of draw \(b\).
The weights must be the same wherever the account is processed, and drawing them must not require knowing the other accounts. We compute \(\xi^{(b)}_a\) from a hash of the account id and the draw number, turned into a uniform number \(U\) and then into an Exponential(1) weight, \(-\log U\). Any machine that holds account \(a\) draws the same weights, as with the Poisson bootstrap. The kernel is written in C++ with Rcpp, like the compression kernel of the previous post. It also contains compress_moments, which builds the compressed dataset of the previous post in the same layout, which we use in the next section.


Code
#include &lt;Rcpp.h&gt;
#include &lt;vector&gt;
#include &lt;cmath&gt;
#include &lt;cstdint&gt;
using namespace Rcpp;

// The bootstrap weight of account a in draw b: a hash of (seed, a, b) turned into an Exponential(1) number.
// Every machine that holds account a computes the same weight, without knowing the other accounts.
inline double xi_weight(uint64_t seed, uint64_t a, uint64_t b) {
  uint64_t z = seed + 0x9E3779B97F4A7C15ULL * (a * 1000003ULL + b + 1);
  z = (z ^ (z &gt;&gt; 30)) * 0xBF58476D1CE4E5B9ULL;
  z = (z ^ (z &gt;&gt; 27)) * 0x94D049BB133111EBULL;
  z = z ^ (z &gt;&gt; 31);
  double U = ((z &gt;&gt; 11) + 0.5) / 9007199254740992.0;          // uniform on (0, 1)
  return -std::log(U);
}

// [[Rcpp::export]]
NumericMatrix bootstrap_weights(IntegerVector account, int B, double seed) {
  NumericMatrix xi(account.size(), B);
  for (int a = 0; a &lt; account.size(); a++)
    for (int b = 0; b &lt; B; b++) xi(a, b) = xi_weight((uint64_t) seed, account[a], b);
  return xi;
}

// Add profile row i into the account summary u = (vec S^Y, vec S, vec S^T), with R = (1, x) and Y the outcome columns.
inline void add_row(std::vector&lt;double&gt;& u, const NumericMatrix& R, const NumericVector& T, const NumericMatrix& Y, int i) {
  int d = R.ncol(), o = Y.ncol();
  for (int l = 0; l &lt; o; l++) for (int j = 0; j &lt; d; j++) u[l * d + j] += R(i, j) * Y(i, l);
  for (int m = 0; m &lt; d; m++) for (int j = 0; j &lt; d; j++) {
    double rr = R(i, j) * R(i, m);
    u[d * o + m * d + j] += rr;
    u[d * o + d * d + m * d + j] += T[i] * rr;
  }
}

// One pass over the profile rows, which must be grouped by account. For every stratum, row b of the output
// is the weighted sum of v_a = (1, u_a) over its accounts, with the bootstrap weights of draw b.
// [[Rcpp::export]]
List compress_bootstrap(IntegerVector account, IntegerVector stratum, NumericMatrix R, NumericVector T,
                        NumericMatrix Y, int n_strata, int B, double seed) {
  int n = R.nrow(), d = R.ncol(), o = Y.ncol(), q = d * o + 2 * d * d;
  std::vector&lt;double&gt; u(q, 0.0), xi(B);
  std::vector&lt;int&gt; nz;
  std::vector&lt;NumericMatrix&gt; sums;
  for (int h = 0; h &lt; n_strata; h++) sums.push_back(NumericMatrix(B, q + 1));
  auto add_account = [&](int a, int h) {
    for (int b = 0; b &lt; B; b++) xi[b] = xi_weight((uint64_t) seed, a, b);   // the account's B weights
    nz.clear();
    for (int k = 0; k &lt; q; k++) if (u[k] != 0) nz.push_back(k);
    double* S = sums[h].begin();                                            // column k + 1 holds entry k of u
    for (int b = 0; b &lt; B; b++) S[b] += xi[b];
    for (int k : nz) {
      double* col = S + (size_t) (k + 1) * B;
      for (int b = 0; b &lt; B; b++) col[b] += xi[b] * u[k];
    }
    for (int k : nz) u[k] = 0;
  };
  for (int i = 0; i &lt; n; i++) {
    if (i &gt; 0 && account[i] != account[i - 1]) add_account(account[i - 1], stratum[i - 1] - 1);
    add_row(u, R, T, Y, i);
  }
  add_account(account[n - 1], stratum[n - 1] - 1);
  List out(n_strata);
  for (int h = 0; h &lt; n_strata; h++) out[h] = sums[h];
  return out;
}

// One pass over the profile rows to the compressed dataset: per stratum, sum v_a and sum v_a v_a^T.
// [[Rcpp::export]]
List compress_moments(IntegerVector account, IntegerVector stratum, NumericMatrix R, NumericVector T,
                      NumericMatrix Y, int n_strata) {
  int n = R.nrow(), d = R.ncol(), o = Y.ncol(), q = d * o + 2 * d * d;
  std::vector&lt;double&gt; v(q + 1, 0.0);
  std::vector&lt;int&gt; nz;
  std::vector&lt;NumericVector&gt; first;
  std::vector&lt;NumericMatrix&gt; second;
  for (int h = 0; h &lt; n_strata; h++) { first.push_back(NumericVector(q + 1)); second.push_back(NumericMatrix(q + 1, q + 1)); }
  auto add_account = [&](int h) {
    v[0] = 1;
    nz.clear();
    for (int k = 0; k &lt;= q; k++) if (v[k] != 0) nz.push_back(k);
    NumericMatrix& S2 = second[h];
    for (size_t i = 0; i &lt; nz.size(); i++) {
      first[h][nz[i]] += v[nz[i]];
      for (size_t j = i; j &lt; nz.size(); j++) S2(nz[j], nz[i]) += v[nz[i]] * v[nz[j]];   // lower triangle
    }
    for (int k : nz) v[k] = 0;
  };
  std::vector&lt;double&gt; u(q, 0.0);
  for (int i = 0; i &lt; n; i++) {
    if (i &gt; 0 && account[i] != account[i - 1]) {
      for (int k = 0; k &lt; q; k++) { v[k + 1] = u[k]; u[k] = 0; }
      add_account(stratum[i - 1] - 1);
    }
    add_row(u, R, T, Y, i);
  }
  for (int k = 0; k &lt; q; k++) v[k + 1] = u[k];
  add_account(stratum[n - 1] - 1);
  List out(n_strata);
  for (int h = 0; h &lt; n_strata; h++) {
    NumericMatrix& S2 = second[h];
    for (int i = 0; i &lt;= q; i++) for (int j = i + 1; j &lt;= q; j++) S2(i, j) = S2(j, i);
    out[h] = List::create(_["first"] = first[h], _["second"] = S2);
  }
  return out;
}


strata numbers the strata, and posterior_one_pass runs the kernel and turns each draw’s 8 weighted sums into effects.


Code
strata &lt;- function(df) {
  accounts &lt;- df |&gt;
    distinct(account, Z, day) |&gt;
    arrange(account)
  keys &lt;- accounts |&gt;
    distinct(Z, day) |&gt;
    arrange(Z, day)
  list(keys = keys, h = match(paste(accounts$Z, accounts$day), paste(keys$Z, keys$day)))
}

posterior_one_pass &lt;- function(df, B, seed) {
  st &lt;- strata(df)
  sums &lt;- compress_bootstrap(df$account, st$h[df$account], centered(df), df$T, as.matrix(df[y_cols]),
                             nrow(st$keys), B, seed)
  posterior_from_sums(st$keys, sums)
}

posterior_from_sums &lt;- function(keys, sums) {      # sums: one B x (1 + q) matrix per stratum
  all_strata &lt;- do.call(cbind, sums)                # row b holds draw b of every stratum, side by side
  map(seq_len(nrow(all_strata)), \(b) fit_sums(keys, matrix(all_strata[b, ], nrow = length(sums), byrow = TRUE))) |&gt;
    do.call(what = rbind)
}

